import (
 "bytes"
 "testing"
 oldproto "github.com/golang/protobuf/proto"
 "github.com/golang/protobuf/ptypes"
 "google.golang.org/grpc/codes"
 "google.golang.org/grpc/encoding"
 _ "google.golang.org/grpc/encoding/proto"
 binlog "google.golang.org/grpc/internal/binarylog"
 legacy "google.golang.org/grpc/reflection/grpc_testing_not_regenerate"
 "google.golang.org/grpc/status"
)

func TestReviewLegacyCodec(t *testing.T) {
 m := &legacy.SearchRequestV3{Query: "hello"}
 expected, err := oldproto.Marshal(m)
 if err != nil { t.Fatal(err) }
 c := encoding.GetCodec("proto")
 data, err := c.Marshal(m)
 if err != nil { t.Errorf("legacy marshal: %v", err) } else if !bytes.Equal(data, expected) { t.Errorf("wire bytes %x != %x", data, expected) }
 out := new(legacy.SearchRequestV3)
 if err := c.Unmarshal(expected, out); err != nil { t.Errorf("legacy unmarshal: %v", err) } else if out.Query != m.Query { t.Errorf("query = %q", out.Query) }
}

func TestReviewLegacyDetails(t *testing.T) {
 m := &legacy.SearchRequestV3{Query: "detail"}
 st, err := status.New(codes.Internal, "failure").WithDetails(m)
 if err != nil { t.Fatal(err) }
 original := &ptypes.DynamicAny{}
 if err := ptypes.UnmarshalAny(st.Proto().Details[0], original); err != nil { t.Fatal(err) }
 if _, ok := original.Message.(*legacy.SearchRequestV3); !ok { t.Fatalf("control type = %T", original.Message) }
 details := st.Details()
 if len(details) != 1 { t.Fatalf("details = %v", details) }
 actual, ok := details[0].(*legacy.SearchRequestV3)
 if !ok { t.Fatalf("Details() returned %T, want *legacy.SearchRequestV3", details[0]) }
 if actual.Query != m.Query { t.Errorf("detail query = %q", actual.Query) }
}

func TestReviewLegacyBinaryLog(t *testing.T) {
 m := &legacy.SearchRequestV3{Query: "logged"}
 expected, err := oldproto.Marshal(m)
 if err != nil { t.Fatal(err) }
 logger := binlog.NewTruncatingMethodLogger(1024, 1024)
 for _, c := range []binlog.LogEntryConfig{&binlog.ClientMessage{Message:m}, &binlog.ServerMessage{Message:m}} {
  entry := logger.Build(c)
  got := entry.GetMessage()
  if !bytes.Equal(got.GetData(), expected) || got.GetLength() != uint32(len(expected)) { t.Errorf("%T logged length=%d data=%x, want length=%d data=%x", c, got.GetLength(), got.GetData(), len(expected), expected) }
 }
}
